// One scripted round per sendMessage call, to drive the tool loop round by round.
const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => {
  const queue = [...rounds];
  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      yield* queue.shift() ?? [];
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
};

const registryReturning = (response: ToolResponse): ToolRegistry => {
  const registry = new ToolRegistry();
  registry.register(
    {name: 'lookup', description: 'looks things up', inputSchema: {type: 'object'}},
    async () => response
  );
  return registry;
};

const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: 'call-1', name: 'lookup', input: {q: 'x'}}};
const STOP_FOR_TOOL: MessageChunk = {type: 'stop', stopReason: 'tool_use'};
const STOP_DONE: MessageChunk = {type: 'stop', stopReason: 'end_turn'};

describe('ChatOrchestrator tool loop', () => {
  it('runs another round after a tool call and streams both rounds in order', async () => {
    const provider = scriptedProvider([
      [{type: 'text', text: 'checking... '}, TOOL_CALL, STOP_FOR_TOOL],
      [{type: 'text', text: 'all done'}, STOP_DONE],
    ]);
    const orchestrator = createChatOrchestrator(provider, promptBuilder, registryReturning({result: 'found it'}));

    const chunks: MessageChunk[] = [];
    for await (const chunk of orchestrator.processMessageStream(createSession('go'))) {
      chunks.push(chunk);
    }

    expect(chunks.map(c => c.type)).toEqual(['text', 'tool_use', 'stop', 'text', 'stop']);
  });

  it('stops after one round when nothing asked for a tool', async () => {
    const provider = scriptedProvider([
      [{type: 'text', text: 'first'}, STOP_DONE],
      [{type: 'text', text: 'never reached'}, STOP_DONE],
    ]);
    const orchestrator = createChatOrchestrator(provider, promptBuilder, registryReturning({result: 'unused'}));

    const result = await orchestrator.processMessage(createSession('go'));

    expect(result).toBe('first');
  });

  it('stops asking for tools once maxToolRounds is spent', async () => {
    const provider = scriptedProvider([
      [TOOL_CALL, STOP_FOR_TOOL],
      [TOOL_CALL, STOP_FOR_TOOL],
      [{type: 'text', text: 'final'}, STOP_DONE],
    ]);
    const orchestrator = createChatOrchestrator(provider, promptBuilder, registryReturning({result: 'ok'}), {
      maxToolRounds: 1,
    });

    const chunks: MessageChunk[] = [];
    for await (const chunk of orchestrator.processMessageStream(createSession('go'))) {
      chunks.push(chunk);
    }

    // maxToolRounds=1: round 0 executes its tool, round 1 sees the result and its own tool request is refused.
    expect(chunks.filter(c => c.type === 'tool_use')).toHaveLength(2);
  });

  it('forwards the client messages a tool returned as one tool_result chunk', async () => {
    const clientMessage: OutgoingMessage = {type: 'entry_commit', index: 0};
    const provider = scriptedProvider([[TOOL_CALL, STOP_FOR_TOOL], [STOP_DONE]]);
    const orchestrator = createChatOrchestrator(
      provider,
      promptBuilder,
      registryReturning({result: 'ok', clientMessages: [clientMessage]})
    );

    const chunks: MessageChunk[] = [];
    for await (const chunk of orchestrator.processMessageStream(createSession('go'))) {
      chunks.push(chunk);
    }

    expect(chunks).toContainEqual({type: 'tool_result', messages: [clientMessage]});
  });

  it('appends an upserted entry to the session and rewrites its index to match', async () => {
    const upserted: SessionEntry = {role: 'assistant', content: 'from tool', timestamp: SENT_AT, isStreaming: false};
    const provider = scriptedProvider([[TOOL_CALL, STOP_FOR_TOOL], [STOP_DONE]]);
    const orchestrator = createChatOrchestrator(
      provider,
      promptBuilder,
      registryReturning({result: 'ok', clientMessages: [{type: 'entry_upsert', index: 99, entry: upserted}]})
    );
    const session = createSession('go');

    const chunks: MessageChunk[] = [];
    for await (const chunk of orchestrator.processMessageStream(session)) {
      chunks.push(chunk);
    }

    const toolChunk = chunks.find((c): c is Extract<MessageChunk, {type: 'tool_result'}> => c.type === 'tool_result');
    expect({entries: session.entries, rewritten: toolChunk?.messages[0]}).toEqual({
      entries: [{role: 'user', content: 'go', timestamp: SENT_AT}, upserted],
      rewritten: {type: 'entry_upsert', index: 1, entry: upserted},
    });
  });

  it('asks for suppression when the tool says the reply is already handled', async () => {
    const provider = scriptedProvider([[TOOL_CALL, STOP_FOR_TOOL], [STOP_DONE]]);
    const orchestrator = createChatOrchestrator(
      provider,
      promptBuilder,
      registryReturning({result: 'ok', suppressAssistantResponse: true})
    );

    const chunks: MessageChunk[] = [];
    for await (const chunk of orchestrator.processMessageStream(createSession('go'))) {
      chunks.push(chunk);
    }

    expect(chunks).toContainEqual({type: 'suppress_output'});
  });

  it('joins the text of every round, not only the last', async () => {
    let reported = '';
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_s, text) => {
        reported = text;
      },
    };
    const provider = scriptedProvider([
      [{type: 'text', text: 'part one '}, TOOL_CALL, STOP_FOR_TOOL],
      [{type: 'text', text: 'part two'}, STOP_DONE],
    ]);
    const orchestrator = createChatOrchestrator(provider, promptBuilder, registryReturning({result: 'ok'}), {hooks});

    const returned = await orchestrator.processMessage(createSession('go'));

    expect({returned, reported}).toEqual({returned: 'part one part two', reported: 'part one part two'});
  });

  it('keeps the usage an earlier round reported when a later round reports none', async () => {
    const usage: UsageMetadata = {inputTokens: 4, outputTokens: 6, totalTokens: 10};
    let reported: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_s, _text, u) => {
        reported = u;
      },
    };
    const provider = scriptedProvider([
      [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage}],
      [{type: 'text', text: 'done'}, STOP_DONE],
    ]);
    const orchestrator = createChatOrchestrator(provider, promptBuilder, registryReturning({result: 'ok'}), {hooks});

    await orchestrator.processMessage(createSession('go'));

    expect(reported).toEqual(usage);
  });

  it('sums the usage of every round that reported one and omits rounds that reported none', async () => {
    let reported: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_s, _text, u) => {
        reported = u;
      },
    };
    const provider = scriptedProvider([
      [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 10, outputTokens: 2, totalTokens: 12}}],
      [TOOL_CALL, STOP_FOR_TOOL],
      [{type: 'text', text: 'done'}, {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 30, outputTokens: 8, totalTokens: 38}}],
    ]);
    const orchestrator = createChatOrchestrator(provider, promptBuilder, registryReturning({result: 'ok'}), {hooks});

    await orchestrator.processMessage(createSession('go'));

    expect(reported).toEqual({inputTokens: 40, outputTokens: 10, totalTokens: 50});
